// Package lru implements a fixed-capacity least-recently-used cache with
// O(1) expected-time operations.
package lru

// nilIdx marks the absence of a node in the intrusive list.
const nilIdx = -1

type node struct {
	key, value string
	prev, next int
}

// Cache is an LRU cache mapping string keys to string values. Entries are
// stored in a slice-backed doubly linked list (front = most recently used)
// so that nodes are reused rather than reallocated. The zero value is not
// usable; create caches with New.
type Cache struct {
	capacity   int
	index      map[string]int
	nodes      []node
	free       []int
	head, tail int
}

// New returns an empty cache holding at most capacity keys. A capacity of
// zero or less yields a cache that never retains anything.
func New(capacity int) *Cache {
	hint := max(capacity, 0) + 1
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int, hint),
		nodes:    make([]node, 0, hint),
		head:     nilIdx,
		tail:     nilIdx,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Set inserts or overwrites key, making it the most recently used. If the
// cache then exceeds its capacity, the least recently used key is evicted.
func (c *Cache) Set(key, value []byte) {
	if i, ok := c.index[string(key)]; ok {
		c.nodes[i].value = string(value)
		c.moveToFront(i)
		return
	}
	i := c.alloc(string(key), string(value))
	c.index[c.nodes[i].key] = i
	c.pushFront(i)
	if len(c.index) > c.capacity {
		c.remove(c.tail)
	}
}

// Get returns the value for key and whether it was present. A hit makes the
// key the most recently used.
func (c *Cache) Get(key []byte) (string, bool) {
	i, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key []byte) bool {
	i, ok := c.index[string(key)]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache) alloc(key, value string) int {
	n := node{key: key, value: value, prev: nilIdx, next: nilIdx}
	if k := len(c.free); k > 0 {
		i := c.free[k-1]
		c.free = c.free[:k-1]
		c.nodes[i] = n
		return i
	}
	c.nodes = append(c.nodes, n)
	return len(c.nodes) - 1
}

// remove unlinks node i, drops it from the index and recycles its slot.
func (c *Cache) remove(i int) {
	c.unlink(i)
	delete(c.index, c.nodes[i].key)
	c.nodes[i] = node{prev: nilIdx, next: nilIdx}
	c.free = append(c.free, i)
}

func (c *Cache) moveToFront(i int) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int) {
	n := &c.nodes[i]
	n.prev = nilIdx
	n.next = c.head
	if c.head != nilIdx {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache) unlink(i int) {
	n := &c.nodes[i]
	if n.prev != nilIdx {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilIdx {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = nilIdx, nilIdx
}

package lru

import "testing"

func get(t *testing.T, c *Cache, key, want string, wantOK bool) {
	t.Helper()
	got, ok := c.Get([]byte(key))
	if ok != wantOK || got != want {
		t.Fatalf("Get(%q) = %q, %v; want %q, %v", key, got, ok, want, wantOK)
	}
}

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := New(2)
	c.Set([]byte("a"), []byte("1"))
	c.Set([]byte("b"), []byte("2"))
	get(t, c, "a", "1", true)
	c.Set([]byte("c"), []byte("3"))
	get(t, c, "b", "", false)
	get(t, c, "a", "1", true)
	get(t, c, "c", "3", true)
	if c.Len() != 2 {
		t.Fatalf("Len() = %d, want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2)
	c.Set([]byte("a"), []byte("1"))
	c.Set([]byte("b"), []byte("2"))
	c.Set([]byte("a"), []byte("9"))
	c.Set([]byte("c"), []byte("3"))
	get(t, c, "a", "9", true)
	get(t, c, "b", "", false)
}

func TestDelete(t *testing.T) {
	c := New(3)
	c.Set([]byte("x"), []byte("1"))
	if !c.Delete([]byte("x")) {
		t.Fatal("first Delete returned false")
	}
	if c.Delete([]byte("x")) {
		t.Fatal("second Delete returned true")
	}
	if c.Len() != 0 {
		t.Fatalf("Len() = %d, want 0", c.Len())
	}
	c.Set([]byte("y"), []byte("2"))
	get(t, c, "y", "2", true)
}

func TestCapacityOne(t *testing.T) {
	c := New(1)
	c.Set([]byte("a"), []byte("1"))
	c.Set([]byte("b"), []byte("2"))
	get(t, c, "a", "", false)
	get(t, c, "b", "2", true)
}

func TestKeyNotAliasedToInput(t *testing.T) {
	c := New(2)
	buf := []byte("k")
	c.Set(buf, []byte("v"))
	buf[0] = 'z'
	get(t, c, "k", "v", true)
}

// Command app simulates an LRU cache: it reads a capacity and a stream of
// SET/GET/DEL/SIZE commands from stdin and writes results to stdout.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	line, rest, ok := nextLine(input)
	if !ok {
		return nil
	}
	cache := lru.New(parseCapacity(line))

	out := bufio.NewWriterSize(w, 1<<16)
	for len(rest) > 0 {
		line, rest, _ = nextLine(rest)
		cmd, args := nextToken(line)
		switch string(cmd) {
		case "SET":
			key, args := nextToken(args)
			value, _ := nextToken(args)
			cache.Set(key, value)
		case "GET":
			key, _ := nextToken(args)
			if value, ok := cache.Get(key); ok {
				out.WriteString(value)
			} else {
				out.WriteString("NULL")
			}
			out.WriteByte('\n')
		case "DEL":
			key, _ := nextToken(args)
			if cache.Delete(key) {
				out.WriteString("1\n")
			} else {
				out.WriteString("0\n")
			}
		case "SIZE":
			out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
			out.WriteByte('\n')
		}
	}
	return out.Flush()
}

// nextLine splits off the first line of data, dropping the terminator and
// any trailing '\r'. It reports false when data is empty.
func nextLine(data []byte) (line, rest []byte, ok bool) {
	if len(data) == 0 {
		return nil, nil, false
	}
	line, rest, _ = bytes.Cut(data, []byte{'\n'})
	return bytes.TrimSuffix(line, []byte{'\r'}), rest, true
}

// nextToken splits off the next space-delimited token.
func nextToken(s []byte) (token, rest []byte) {
	token, rest, _ = bytes.Cut(s, []byte{' '})
	return token, rest
}

// parseCapacity reads the leading decimal digits of s, ignoring anything
// after them.
func parseCapacity(s []byte) int {
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			break
		}
		n = n*10 + int(c-'0')
	}
	return n
}
